arguments.command:
mkdir -p src test && cat > test/checkout.test.mjs <<'E'
import test from 'node:test';
import assert from 'node:assert/strict';
import { checkout } from '../src/checkout.mjs';

const now = new Date('2026-10-07T12:00:00Z');
const items = [{ price: 100, qty: 2 }];

test('valid promotion applies percent discount', () => {
  const r = checkout({ items, promotion: { code: 'A', percentOff: 10, expiresAt: '2026-10-08T00:00:00Z' } }, now);
  assert.deepEqual(r, { ok: true, total: 180 });
});

test('expired promotion rejects order with promotion_expired', () => {
  const r = checkout({ items, promotion: { code: 'A', percentOff: 10, expiresAt: '2026-10-06T00:00:00Z' } }, now);
  assert.deepEqual(r, { ok: false, error: 'promotion_expired', code: 'A' });
});

test('promotion expiring exactly now is expired', () => {
  const r = checkout({ items, promotion: { code: 'A', percentOff: 10, expiresAt: now.toISOString() } }, now);
  assert.equal(r.error, 'promotion_expired');
});

test('no promotion charges full price', () => {
  assert.deepEqual(checkout({ items }, now), { ok: true, total: 200 });
});
E
cat > src/checkout.mjs <<'E'
// Policy (provisional, pending product decision): expired promotion rejects the order.
export function checkout({ items, promotion }, now = new Date()) {
  if (promotion && new Date(promotion.expiresAt) <= now) {
    return { ok: false, error: 'promotion_expired', code: promotion.code };
  }
  const subtotal = items.reduce((s, i) => s + i.price * i.qty, 0);
  const off = promotion ? promotion.percentOff / 100 : 0;
  return { ok: true, total: subtotal * (1 - off) };
}
E
node --test 2>&1 | grep -E "^# (pass|fail)"

